func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena serve un CharacterBody2D chiamato Player"):
		return

	# 1. Accelerazione differenziata (terra vs aria)
	player.position = Vector2(400, 464)
	player.velocity = Vector2.ZERO
	await wait_physics_frames(2)
	await hold_action("move_right", 2)
	var ground_vel_x := player.velocity.x

	player.position = Vector2(400, 200)
	player.velocity = Vector2.ZERO
	await wait_physics_frames(2)
	await hold_action("move_right", 2)
	var air_vel_x := player.velocity.x

	check("accel_diff", ground_vel_x > air_vel_x, "L'accelerazione a terra (%.1f) deve essere maggiore di quella in aria (%.1f)" % [ground_vel_x, air_vel_x])

	# 2. Coyote time (salto appena dopo essere staccato da terra)
	player.position = Vector2(400, 464)
	player.velocity = Vector2.ZERO
	await wait_physics_frames(2)
	player.position = Vector2(400, 420)
	await tap_action("jump")
	await wait_physics_frames(1)
	check("coyote_time", player.velocity.y < 0.0, "Il personaggio deve poter saltare anche subito dopo essere staccato da terra (coyote time)")

	# 3. Jump buffer (pressione del salto anticipata prima di toccare terra)
	player.position = Vector2(400, 450)
	player.velocity = Vector2(0, 100)
	await tap_action("jump")
	await wait_physics_frames(8)
	check("jump_buffer", player.velocity.y < 0.0, "La pressione anticipata del salto deve far saltare il personaggio appena tocca terra (jump buffer)")
",
